    act(() => {
      result.current.bootstrapSession([], runA);
    });
    rerender({ sessionId: sessionB, transport: transportB });
    act(() => {
      result.current.bootstrapSession(
        [
          {
            id: "user-b",
            role: "user",
            content: "session B",
            blocks: [],
