    let promptPromise: Promise<void> | null = null;
    await act(async () => {
      promptPromise = result.current.sendPrompt("keep working");
      await Promise.resolve();
    });
    await waitFor(() => {
      expect(result.current.runState).toBe("running");
    });

    await act(async () => {
      await result.current.cancel();
