      await promptPromise;
    });
    expect(result.current.runState).toBe("idle");
  });

  it("replays a queued steering prompt after the current run completes", async () => {
    const firstTurnFinished = createDeferredPromise();

    streamPromptMock
      .mockImplementationOnce(async function* () {
