        maxSessionBytes: RUNTIME_TRANSPORT_SESSION_BYTES,
        capabilityEndpoint: "/api/runtime/capabilities",
      });
      entry = {
        connection,
        tail: Promise.resolve(),
        retired: false,
        successfulHistoryRequests: 0,
      };
