221	  let consumed = false;
222	
223	  return {
224	    runId,
225	    async *events(): AsyncGenerator<SSEEvent> {
226	      if (consumed) {
227	        throw new Error("Prompt event stream can only be consumed once");
228	      }
229	      consumed = true;
230	      let nextSequence = 0;
231	      let retryDelayMs = pollDelayMs;
232	      let consecutiveTransientFailures = 0;
233	      let emittedTerminalEvent = false;
234	      while (true) {
235	        if (options.signal?.aborted) throw abortError();
236	        let rawBatch: unknown;
237	        try {
238	          rawBatch = await transport.get<unknown>(
239	            `/api/sessions/${sessionId}/runs/${runId}/events/${nextSequence}`,
240	          );
241	        } catch (error) {
242	          if (!shouldRetry(error)) throw error;
243	          consecutiveTransientFailures += 1;
244	          if (consecutiveTransientFailures >= pollRetryLimit) throw error;
245	          retryDelayMs = Math.min(Math.max(retryDelayMs * 2, 250), 5_000);
