247	          continue;
248	        }
249	        const batch = validateBatch(rawBatch, runId, nextSequence);
250	        consecutiveTransientFailures = 0;
251	        retryDelayMs = pollDelayMs;
252	        nextSequence = batch.nextSequence;
253	        for (const event of batch.events) {
254	          if (
255	            event.type === "error" ||
256	            event.type === "cancelled" ||
257	            event.type === "result"
258	          ) {
259	            emittedTerminalEvent = true;
260	          }
261	          yield event;
262	        }
