204	  let cursor: string | null = null;
205	  let pageRequests = 0;
206	
207	  while (true) {
208	    assertNotCancelled(options);
209	    pageRequests += 1;
210	    if (pageRequests > MAX_HISTORY_PAGE_REQUESTS) {
211	      throw new Error("Message history used too many page requests");
212	    }
213	    const cursorKey = cursor ?? "<initial>";
214	    if (seenCursors.has(cursorKey)) {
215	      throw new Error("Message history cursor did not advance");
216	    }
217	    seenCursors.add(cursorKey);
218	    const path = cursor
