228	      if (seenMessageIds.has(message.id)) {
229	        throw new Error("Message history repeated a message");
230	      }
231	      seenMessageIds.add(message.id);
232	      metadata.push(message);
233	      if (metadata.length > MAX_HISTORY_MESSAGES) {
234	        throw new Error("Message history contains too many messages");
235	      }
236	    }
237	    if (page.next_cursor === null) break;
238	    if (page.messages.length === 0 || seenCursors.has(page.next_cursor)) {
239	      throw new Error("Message history cursor did not advance");
240	    }
241	    cursor = page.next_cursor;
242	  }
243	
244	  const budget: RequestBudget = { fieldRequests: 0 };
245	  const messages: Message[] = [];
246	  for (const message of metadata) {
247	    const content = await loadHistoryField(
248	      transport,
249	      sessionId,
250	      message.id,
251	      "content",
252	      message.content_length,
253	      budget,
254	      options,
