303	      try {
304	        await consumeEvents(
305	          runtimePrompt.events(),
306	          runtimePrompt.runId,
307	          generation,
308	          operation,
309	        );
310	      } finally {
311	        if (!isCurrent(generation, operation)) return;
312	        abortRef.current = null;
313	        promptHandleRef.current = null;
314	        promptStartRef.current = null;
315	        const queuedPrompt = queuedPromptRef.current;
316	        queuedPromptRef.current = null;
317	        updateRunState("idle");
318	        if (queuedPrompt) {
319	          void startPrompt(
320	            queuedPrompt.prompt,
321	            queuedPrompt.model,
322	            queuedPrompt.thinking,
323	          );
324	        }
325	      }
326	    },
327	    [
328	      consumeEvents,
329	      isCurrent,
330	      runtimeTransport,
331	      sessionId,
332	      startPrompt,
333	      updateRunState,
334	    ],
335	  );
336	
337	  const bootstrapSession = useCallback(
338	    (history: ChatMessage[], activeRunId: string | null): void => {
339	      if (
340	        contextRef.current.sessionId !== sessionId ||
341	        contextRef.current.runtimeTransport !== runtimeTransport
342	      ) {
343	        return;
344	      }
345	      operationRef.current += 1;
346	      abortRef.current?.abort();
347	      abortRef.current = null;
348	      promptHandleRef.current = null;
349	      promptStartRef.current = null;
350	      queuedPromptRef.current = null;
351	      cancelInFlightRef.current = false;
352	      updateRunState("idle");
353	      setMessages(history);
354	      if (activeRunId !== null) void resumePrompt(activeRunId);
355	    },
356	    [resumePrompt, runtimeTransport, sessionId, updateRunState],
357	  );
358	
359	  const cancel = useCallback(async () => {
360	    if (runStateRef.current !== "running" || cancelInFlightRef.current) return;
361	    const generation = generationRef.current;
362	    const operation = operationRef.current;
363	    cancelInFlightRef.current = true;
364	    const activeController = abortRef.current;
365	    updateRunState("stopping");
366	    try {
367	      if (sessionId) {
368	        if (runtimeTransport) {
369	          const promptHandle =
370	            promptHandleRef.current ?? (await promptStartRef.current);
371	          if (promptHandle) await promptHandle.cancel();
372	        } else {
373	          await cancelSession(sessionId);
374	        }
375	      }
376	    } catch {
377	      if (!isCurrent(generation, operation)) return;
378	      if (activeController !== null && abortRef.current === activeController) {
379	        updateRunState("running");
380	      }
381	      setMessages((previous) => [
382	        ...previous,
383	        {
384	          id: nextId(),
385	          role: "error",
386	          content: CANCELLATION_ERROR_MESSAGE,
387	          blocks: [],
388	          timestamp: Date.now(),
389	        },
390	      ]);
391	    } finally {
392	      if (isCurrent(generation, operation)) cancelInFlightRef.current = false;
393	    }
394	  }, [isCurrent, runtimeTransport, sessionId, updateRunState]);
395	
396	  const sendPrompt = useCallback(
397	    async (prompt: string, model?: string, thinking?: ThinkingLevel) => {
398	      if (!sessionId) return;
399	      const normalizedPrompt = prompt.trim();
400	      if (!normalizedPrompt) return;
401	
402	      if (runStateRef.current === "running") {
403	        queuedPromptRef.current = { prompt: normalizedPrompt, model, thinking };
404	        await cancel();
405	        return;
406	      }
407	      if (runStateRef.current === "stopping") {
408	        queuedPromptRef.current = { prompt: normalizedPrompt, model, thinking };
409	        return;
410	      }
411	      await startPrompt(normalizedPrompt, model, thinking);
412	    },
413	    [cancel, sessionId, startPrompt],
414	  );
415	
416	  return {
417	    messages,
418	    sendPrompt,
419	    cancel,
420	    runState,
421	    setMessages,
422	    bootstrapSession,
423	    streaming: runState === "running" || runState === "stopping",
424	  };
425	}
